example_item.example_item_data:
% Afficher le rapport d'etude d'un enregistrement simule a douze derivations.
recording = ecglab.simulate('Seconds', 30, 'Rate', 500, 'Leads', 12, 'Seed', 1);
ecglab.report(recording);

% Recuperer le rapport sous forme de texte et l'ecrire aussi dans un fichier.
recording = ecglab.simulate('Seconds', 30, 'Rate', 500, 'Leads', 12, 'Seed', 1);
text = ecglab.report(recording, 'File', [tempdir(), 'ecg_report.txt']);
disp(text(1:60))
